"""Regress the real lock changes generated by uv, not only hand-written locks."""

import tomllib
from pathlib import Path

import pytest

from l5_services.adapters.transform.dependency_oracle import compare_dependency_upgrade


FIXTURE = Path(__file__).parent / "fixtures/uv-generated-upgrade"
TARGET = {"kind": "dependency", "name": "packaging", "version": "25.0"}


def inputs():
    base, candidate = ({name: (FIXTURE / stage / name).read_bytes() for name in ("pyproject.toml", "uv.lock")}
                       for stage in ("base", "candidate"))
    selected = next(package for package in tomllib.loads(candidate["uv.lock"].decode())["package"]
                    if package["name"] == "packaging")
    hashes = [selected["sdist"]["hash"], *[wheel["hash"] for wheel in selected["wheels"]]]
    return base, candidate, hashes


@pytest.mark.parametrize("source", [b"virtual", b"editable"])
def test_accepts_real_uv_selected_root_requirement_mirror(source):
    base, candidate, hashes = inputs()
    for files in (base, candidate):
        files["uv.lock"] = files["uv.lock"].replace(b"virtual", source)
    result = compare_dependency_upgrade(base, candidate, TARGET, hashes)
    assert result["base_version"] == "24.2"
    assert result["candidate_version"] == "25.0"
    assert result["artifact_hashes"] == sorted(hashes)


@pytest.mark.parametrize("fault", ["specifier", "name", "marker", "extras", "duplicate", "source", "version",
                                  "root_dependencies", "missing_metadata", "unrelated_package"])
def test_required_root_mirror_does_not_allow_other_lock_changes(fault):
    base, candidate, hashes = inputs()
    old = b'requires-dist = [{ name = "packaging", specifier = "==25.0" }]'
    changed = {
        "specifier": b'requires-dist = [{ name = "packaging", specifier = ">=25.0" }]',
        "name": b'requires-dist = [{ name = "other", specifier = "==25.0" }]',
        "marker": b'requires-dist = [{ name = "packaging", specifier = "==25.0", marker = "python_version >= \'3.12\'" }]',
        "extras": b'requires-dist = [{ name = "packaging", specifier = "==25.0", extras = ["unexpected"] }]',
        "duplicate": b'requires-dist = [{ name = "packaging", specifier = "==25.0" }, { name = "packaging", specifier = "==25.0" }]',
        "missing_metadata": b'requires-dist = []',
    }
    if fault in changed:
        candidate["uv.lock"] = candidate["uv.lock"].replace(old, changed[fault])
    elif fault == "source":
        candidate["uv.lock"] = candidate["uv.lock"].replace(b'virtual = "."', b'editable = "."')
    elif fault == "version":
        candidate["uv.lock"] = candidate["uv.lock"].replace(b'version = "1.0.0"', b'version = "1.0.1"')
    elif fault == "root_dependencies":
        candidate["uv.lock"] = candidate["uv.lock"].replace(b'{ name = "packaging" },', b'{ name = "unexpected" },')
    else:
        candidate["uv.lock"] += b'\n[[package]]\nname = "unexpected"\nversion = "1.0.0"\n'
    with pytest.raises(ValueError):
        compare_dependency_upgrade(base, candidate, TARGET, hashes)


def test_root_metadata_cannot_hide_wrong_baseline_specifier():
    base, candidate, hashes = inputs()
    base["uv.lock"] = base["uv.lock"].replace(b'specifier = "==24.2"', b'specifier = "==23.0"')
    with pytest.raises(ValueError, match="selected manifest version"):
        compare_dependency_upgrade(base, candidate, TARGET, hashes)
